/* Original recipe and local-discovery scenes. No remote requests or accounts. */
(() => {
  'use strict';
  const recipes = [
    {id:'ginger-rice',name:['One-pan ginger chicken & rice','一锅姜香鸡肉饭'],category:'one-pot',tag:['The weeknight favourite','平日晚餐首选'],time:35,prep:10,cook:25,color:'#e0b26e',dark:'#93603b',kind:'rice',desc:['Fragrant rice, tender chicken and a bright cucumber finish. One pan does the work while you get the table ready.','姜香米饭、鲜嫩鸡肉，加上清爽黄瓜。一口锅就能做好的一餐。'],ingredients:[[250,'g','boneless chicken thigh','去骨鸡腿肉'],[180,'g','jasmine rice, rinsed','洗净的茉莉香米'],[300,'ml','water or unsalted stock','水或无盐高汤'],[20,'g','ginger, finely sliced','姜丝'],[2,'cloves','garlic, chopped','蒜末'],[1,'tbsp','light soy sauce','生抽'],[1,'tsp','sesame oil','芝麻油'],[0.5,'','cucumber, sliced','黄瓜，切片']],steps:[['Pat the chicken dry and cut into bite-sized pieces. Toss with the soy sauce and half the ginger.','鸡肉擦干并切成小块，与生抽和一半姜丝拌匀。'],['Heat a little oil in a heavy pan over medium heat. Cook the garlic and remaining ginger for 30 seconds; add chicken and turn until the outside changes colour.','厚底锅中火热少许油，炒香蒜末和剩余姜丝约 30 秒；加入鸡肉，翻炒至表面变色。'],['Stir in the drained rice, then add the water. Bring to a gentle simmer, cover and turn the heat to low for 18 minutes.','加入沥干的米拌匀，再加入水。微沸后盖锅盖，小火煮 18 分钟。'],['Check that the chicken is cooked through with no pink centre (74°C if using a thermometer). If needed, cook a little longer. Rest off the heat, covered, for 5 minutes.','确认鸡肉中心完全熟透（温度计测得 74°C）。必要时继续煮。关火盖盖焖 5 分钟。'],['Fluff the rice, drizzle with sesame oil and serve with cucumber. Add chilli sauce at the table if you like.','拨松米饭，淋上芝麻油，配黄瓜食用。喜欢辣味可以另外加辣椒酱。']],tip:['Use firm tofu and vegetable stock for a meat-free version. Add the tofu with the rice.','素食版可用硬豆腐和蔬菜高汤，豆腐与米一起加入。'],storage:['Cool leftovers promptly, refrigerate within two hours and eat within one day. Reheat until steaming hot.','剩饭及时冷却，两小时内冷藏，次日内吃完；重新加热至完全热透。']},
    {id:'tomato-pasta',name:['Roasted tomato & basil pasta','烤番茄罗勒意面'],category:'vegetarian',tag:['A little oven magic','烤箱里的简单美味'],time:30,prep:10,cook:20,color:'#c64e2d',dark:'#e3a64a',kind:'pasta',desc:['Sweet blistered tomatoes turn into a silky sauce with a splash of pasta water. Finish with torn basil and plenty of black pepper.','烤出甜味的番茄，加上少许煮面水变成丝滑酱汁。最后撒上罗勒和黑胡椒。'],ingredients:[[180,'g','dried pasta','干意面'],[350,'g','cherry tomatoes','樱桃番茄'],[2,'tbsp','olive oil','橄榄油'],[3,'cloves','garlic, peeled','去皮蒜瓣'],[15,'g','fresh basil','新鲜罗勒'],[25,'g','grated hard cheese, optional','硬质奶酪碎，可选'],[0.5,'tsp','salt, plus water seasoning','盐，另备少许煮面']],steps:[['Heat the oven to 200°C. Put tomatoes and garlic in a roasting dish; toss with oil and salt.','烤箱预热至 200°C。番茄和蒜放入烤盘，与油和盐拌匀。'],['Roast for 20 minutes until the tomatoes wrinkle and release their juices.','烤 20 分钟，直到番茄起皱并流出汁水。'],['Meanwhile cook pasta in salted boiling water following its packet. Reserve a mug of cooking water before draining.','同时按照包装指示，用加盐的沸水煮意面。沥水前留一杯煮面水。'],['Mash the roasted garlic and a few tomatoes with a fork. Toss pasta into the dish, adding splashes of cooking water until glossy.','用叉子压碎烤蒜和部分番茄。加入意面拌匀，少量多次加煮面水，直到酱汁有光泽。'],['Tear over basil, add cheese if using, and finish with black pepper.','撕入罗勒，按喜好加入奶酪，最后撒上黑胡椒。']],tip:['No fresh basil? Use a teaspoon of dried oregano before roasting. Omit cheese for a plant-based bowl.','没有新鲜罗勒可在烤前加入一茶匙干牛至。不加奶酪即可做成植物性餐点。'],storage:['Refrigerate in a covered container for up to two days. Loosen with a little water when reheating.','密封冷藏最多两天。加热时加一点水，让酱汁恢复顺滑。']},
    {id:'chilli-tofu',name:['Sticky sesame tofu bowls','芝麻酱香豆腐饭'],category:'vegetarian',tag:['Crisp edges, sticky sauce','外脆内嫩，浓郁酱香'],time:25,prep:10,cook:15,color:'#bd7a41',dark:'#7f432b',kind:'tofu',desc:['Golden cubes of tofu in a savoury sesame glaze. Serve over rice with crunchy vegetables for a satisfying pantry dinner.','金黄豆腐裹上咸香芝麻酱汁，配米饭和爽口蔬菜，就是一碗满足的晚餐。'],ingredients:[[300,'g','firm tofu','硬豆腐'],[2,'tbsp','cornflour','玉米淀粉'],[1,'tbsp','neutral cooking oil','食用油'],[2,'tbsp','light soy sauce','生抽'],[1,'tbsp','honey or maple syrup','蜂蜜或枫糖浆'],[1,'tsp','rice vinegar','米醋'],[1,'tsp','sesame seeds','芝麻'],[250,'g','cooked rice','熟米饭'],[150,'g','broccoli or cucumber','西兰花或黄瓜']],steps:[['Drain tofu and press gently between clean towels for 5 minutes. Cut into 2 cm cubes.','豆腐沥干，用干净毛巾轻压 5 分钟，切成 2 厘米小块。'],['Coat cubes in cornflour. Heat oil in a non-stick pan and fry the tofu for 8–10 minutes, turning until golden.','豆腐裹上淀粉。不粘锅热油，煎 8–10 分钟，翻面至金黄。'],['Mix soy sauce, honey, vinegar and 2 tablespoons of water. Pour into the pan and bubble gently for a minute.','混合生抽、蜂蜜、米醋和两汤匙水。倒入锅中，小火煮约一分钟。'],['Steam broccoli until just tender, or slice cucumber. Divide warm rice between bowls.','西兰花蒸至刚好熟软，或将黄瓜切片。把热米饭盛入碗中。'],['Top rice with tofu and vegetables. Spoon over the glaze and scatter sesame seeds.','米饭上摆好豆腐和蔬菜，淋上酱汁并撒芝麻。']],tip:['Add chilli flakes to the glaze for heat. Use tamari instead of soy sauce if a gluten-free version is needed.','喜欢辣味可加辣椒碎。需要无麸质版本时，使用适合的无麸质酱油。'],storage:['Keep rice and tofu separately in the fridge and use within one day. Reheat thoroughly.','米饭和豆腐分开冷藏，次日内吃完，加热至完全热透。']},
    {id:'coconut-noodles',name:['Coconut curry noodle soup','椰香咖喱汤面'],category:'one-pot',tag:['Comfort in a bowl','一碗暖心好滋味'],time:25,prep:10,cook:15,color:'#dd9b3c',dark:'#9c502d',kind:'soup',desc:['An easy, gently spiced coconut broth with noodles, mushrooms and greens. A squeeze of lime makes everything sing.','温和香浓的椰奶汤底，配面条、蘑菇和青菜，最后挤一点青柠汁提味。'],ingredients:[[180,'g','rice noodles','米粉'],[200,'ml','coconut milk','椰奶'],[400,'ml','vegetable stock','蔬菜高汤'],[1,'tbsp','mild curry paste','温和咖喱酱'],[120,'g','mushrooms, sliced','蘑菇，切片'],[100,'g','pak choi','小白菜'],[1,'','lime','青柠'],[1,'tsp','soy sauce','生抽']],steps:[['Prepare noodles following the packet, then drain. Slice mushrooms and separate the pak choi leaves.','按包装指示泡或煮米粉后沥干。蘑菇切片，小白菜分开叶片。'],['Warm a little oil in a saucepan. Stir the curry paste over medium heat for 30 seconds.','汤锅热少许油，中火炒咖喱酱 30 秒。'],['Add stock and coconut milk, stir well and bring to a gentle simmer. Add mushrooms and cook for 5 minutes.','加入高汤和椰奶拌匀，小火微煮。加入蘑菇，煮 5 分钟。'],['Add pak choi and soy sauce. Cook for 2 minutes until the greens soften but stay bright.','加入小白菜和生抽，煮 2 分钟，保持青菜鲜绿。'],['Divide noodles into bowls, pour over hot broth and finish with lime juice to taste.','米粉盛入碗里，倒入热汤，按喜好挤入青柠汁。']],tip:['Check curry-paste ingredients for shrimp if cooking for vegetarians or anyone with a shellfish allergy.','为素食者或贝类过敏者烹饪时，检查咖喱酱是否含虾。'],storage:['Chill broth separately from noodles for up to two days. Reheat gently without hard boiling.','汤和面分开冷藏最多两天。小火加热，避免猛烈沸腾。']},
    {id:'egg-toast',name:['Soft eggs on chilli-butter toast','辣椒黄油鸡蛋吐司'],category:'quick',tag:['Breakfast, any time','随时都想吃的早餐'],time:15,prep:5,cook:10,color:'#e4bd57',dark:'#b47b43',kind:'toast',desc:['Creamy scrambled eggs on crisp toast, finished with a small spoon of chilli butter and fresh spring onion.','绵软炒蛋配香脆吐司，再加一小勺辣椒黄油和新鲜葱花。'],ingredients:[[4,'','eggs','鸡蛋'],[4,'slices','bread','面包片'],[20,'g','butter','黄油'],[1,'tbsp','milk','牛奶'],[0.25,'tsp','chilli flakes','辣椒碎'],[1,'','spring onion','青葱'],[0.25,'tsp','salt','盐']],steps:[['Whisk eggs with milk and salt. Slice the spring onion thinly.','鸡蛋与牛奶和盐打匀，青葱切细。'],['Toast bread until crisp. Melt half the butter in a small pan and briefly stir in chilli flakes; set aside.','面包烤至香脆。小锅融化一半黄油，稍微炒香辣椒碎后盛出。'],['Melt remaining butter in a non-stick pan over low heat. Add eggs and slowly fold with a spatula.','不粘锅小火融化剩余黄油。倒入蛋液，用锅铲缓缓推拌。'],['Remove from heat once the eggs are softly set and fully cooked. Residual heat will keep cooking them.','鸡蛋完全凝固而仍然软嫩时离火，余温会继续加热。'],['Spoon onto toast, drizzle with chilli butter and scatter spring onion. Eat straight away.','鸡蛋放上吐司，淋辣椒黄油，撒葱花，趁热享用。']],tip:['Swap chilli butter for plain butter for a milder breakfast. Rye or sourdough both work beautifully.','不吃辣可用原味黄油。黑麦面包或酸种面包都很适合。'],storage:['Best eaten fresh. Keep cooked egg leftovers refrigerated and eat within one day.','现做现吃最佳。熟鸡蛋剩余部分冷藏并在次日内吃完。']},
    {id:'lemon-fish',name:['Lemon fish & tray-baked vegetables','柠檬烤鱼配蔬菜'],category:'one-pot',tag:['Less washing up','少洗几个碗'],time:35,prep:10,cook:25,color:'#d6bb84',dark:'#c5aa70',kind:'fish',desc:['A colourful tray of vegetables with flaky white fish and lemon. The vegetables get a head start so everything finishes together.','一盘缤纷蔬菜配上细嫩白鱼和柠檬。先烤蔬菜，让整盘食材同时熟透。'],ingredients:[[300,'g','white fish fillets, boneless','去骨白鱼柳'],[250,'g','small potatoes, thinly sliced','小土豆，切薄片'],[1,'','courgette, sliced','西葫芦，切片'],[150,'g','cherry tomatoes','樱桃番茄'],[1,'','lemon','柠檬'],[2,'tbsp','olive oil','橄榄油'],[0.5,'tsp','dried oregano','干牛至']],steps:[['Heat oven to 200°C. Toss thinly sliced potatoes with half the oil and spread in one layer on a roasting tray.','烤箱预热至 200°C。土豆薄片与一半橄榄油拌匀，在烤盘铺成一层。'],['Roast potatoes for 12 minutes, then add courgette and tomatoes with the remaining oil.','土豆先烤 12 分钟，再加入西葫芦、番茄和剩余油。'],['Season the fish with oregano, salt and pepper. Place on the vegetables and add lemon slices.','鱼柳撒牛至、盐和胡椒，放在蔬菜上，再铺柠檬片。'],['Roast for 12–15 minutes until fish is opaque and flakes easily (63°C in the thickest part).','继续烤 12–15 分钟，至鱼肉不透明且容易分开（最厚处达 63°C）。'],['Check the potatoes are tender, then serve with the tray juices and another squeeze of lemon.','确认土豆熟软，淋上烤盘里的汁水，再挤少许柠檬汁。']],tip:['Use thin potato slices so they cook in time. Frozen fish should be completely defrosted first.','土豆切薄才能及时烤熟。冷冻鱼柳需先彻底解冻。'],storage:['Cover and refrigerate leftovers promptly; eat within one day and reheat thoroughly.','剩余食材及时密封冷藏，次日内吃完并彻底加热。']},
    {id:'peanut-noodles',name:['Crunchy peanut noodle salad','香脆花生凉拌面'],category:'quick',tag:['Lunch, sorted','午餐有着落了'],time:15,prep:10,cook:5,color:'#c99255',dark:'#9e6334',kind:'pasta',desc:['Cool noodles, crisp vegetables and a creamy peanut-lime dressing. Make the dressing while the noodles cook.','凉爽面条、爽脆蔬菜，配上花生青柠酱汁。煮面时就能做好酱汁。'],ingredients:[[160,'g','wheat noodles','小麦面条'],[2,'tbsp','smooth peanut butter','顺滑花生酱'],[1,'tbsp','soy sauce','生抽'],[1,'','lime','青柠'],[1,'tsp','sugar','糖'],[1,'','carrot, grated','胡萝卜，刨丝'],[0.5,'','cucumber, sliced','黄瓜，切丝'],[20,'g','roasted peanuts','烤花生']],steps:[['Cook noodles following packet directions. Drain, rinse under cool water and drain well again.','按照包装指示煮面。沥干，用凉水冲洗后再次彻底沥干。'],['Whisk peanut butter, soy sauce, lime juice and sugar with 2–3 tablespoons of warm water.','将花生酱、生抽、青柠汁和糖，与 2–3 汤匙温水搅匀。'],['Grate carrot, slice cucumber and roughly chop peanuts.','胡萝卜刨丝、黄瓜切丝，花生粗切。'],['Toss noodles with the dressing and vegetables until evenly coated. Taste and add more lime if needed.','面条与酱汁和蔬菜拌匀，尝味后按需补加青柠汁。'],['Divide between bowls and finish with peanuts. Add sliced spring onion if you have it.','分装入碗，撒花生，也可以加上葱花。']],tip:['Contains peanuts. For a peanut-free version, use a suitable seed butter and omit the topping.','含花生。无花生版可改用合适的种子酱，并省略花生配料。'],storage:['Keep covered in the fridge for up to two days. Add a splash of water to loosen the dressing.','密封冷藏最多两天。食用前加少许水拌开酱汁。']},
    {id:'mushroom-skillet',name:['Garlic mushrooms on creamy beans','蒜香蘑菇奶油白豆'],category:'vegetarian',tag:['Simple pantry comfort','储物柜里的暖心料理'],time:20,prep:5,cook:15,color:'#9a7350',dark:'#6c513c',kind:'beans',desc:['Golden mushrooms over soft white beans, with lemon and herbs. Keep a slice of bread nearby for the last of the sauce.','金黄蘑菇配软糯白豆，柠檬与香草提味。备一片面包，蘸干净最后一点酱汁。'],ingredients:[[250,'g','mushrooms, sliced','蘑菇，切片'],[400,'g','canned white beans, drained','白豆罐头，沥干'],[2,'cloves','garlic, chopped','蒜末'],[100,'ml','vegetable stock','蔬菜高汤'],[2,'tbsp','plain yoghurt','原味酸奶'],[1,'tbsp','olive oil','橄榄油'],[0.5,'','lemon','柠檬'],[10,'g','parsley','欧芹']],steps:[['Pat mushrooms dry. Heat oil in a wide pan over medium-high heat and spread mushrooms in a single layer.','蘑菇擦干。宽平底锅中大火热油，将蘑菇尽量铺成单层。'],['Leave for 3 minutes before stirring. Cook for another 3 minutes until golden, then add garlic for 30 seconds.','先煎 3 分钟再翻动。再煎 3 分钟至金黄，加入蒜末炒 30 秒。'],['Add drained beans and stock. Simmer for 5 minutes and gently crush a few beans to thicken the sauce.','加入沥干白豆和高汤，煮 5 分钟，轻压部分白豆让酱汁浓稠。'],['Turn off the heat, then stir in yoghurt, lemon juice and chopped parsley. Season to taste.','关火后拌入酸奶、柠檬汁和欧芹碎，按口味调味。'],['Spoon into shallow bowls and serve with warm bread.','盛入浅碗，配温热面包食用。']],tip:['Stir yoghurt in off the heat to keep it smooth. A spoonful of tahini works as a dairy-free alternative.','关火后才加入酸奶以免结块。无乳制品版可用一勺芝麻酱代替。'],storage:['Refrigerate for up to two days. Warm gently and stir well before serving.','冷藏最多两天。小火加热，食用前充分拌匀。']}
  ];
  const outings = [
    {id:'lake-morning',name:['A slow morning around the lake','湖畔的慢早晨'],place:['Perdana Botanical Gardens','吉隆坡湖滨植物园'],area:'KL',category:'outdoors',cost:0,hours:3,color:'#87a89a',accent:'#d5dfb3',style:'lake',summary:['A leafy walk, a flask of coffee and an unhurried picnic. A gentle city escape that leaves the rest of your day open.','沿绿荫慢走、带一壶咖啡、铺开野餐垫。轻松离开城市节奏，又留出一整天的余裕。'],route:['Walk in from the main garden paths and spend the first half hour finding a shaded route.','从花园主要步道进入，先用半小时寻找一条有树荫的路线。'],itinerary:[['08:00','Arrive early for cooler paths. Walk the shaded perimeter without rushing.','早点抵达，趁天气凉爽慢慢走树荫步道。'],['09:00','Pause near the lake. Bring a flask and a small breakfast; take all packaging home.','湖边休息，自备饮料和早餐，并带走所有包装。'],['10:00','Explore a different garden path on the way out, then find lunch in the city.','离开时走另一条花园步道，再到市区找午餐。']],bring:['Water, sun protection, a small mat and comfortable shoes.','水、防晒、小野餐垫和舒适的鞋。'],transport:['Plan a short walk or a final ride-hailing leg from a nearby rail stop. The garden is hilly in places.','可从附近轨道站步行或短程叫车。花园部分路段有坡度。'],rain:['Move the picnic to a sheltered café and keep the garden walk for a dry morning.','雨天改到有遮蔽的咖啡馆，把花园散步留给晴天。']},
    {id:'old-town',name:['The old-city photo walk','老城区摄影散步'],place:['Kwai Chai Hong & Chinatown','鬼仔巷与茨厂街'],area:'KL',category:'culture',cost:25,hours:4,color:'#b77458',accent:'#f4d995',style:'street',summary:['Laneways, tiled five-foot ways and a lunch stop. Look up at the old façades and slow down between the busy streets.','小巷、骑楼、午餐小店。抬头看看旧店屋，在繁忙街道间慢下来。'],route:['Start around Pasar Seni and connect the lanes on foot rather than crossing the city by car.','以中央艺术坊一带为起点，步行连接附近巷弄，避免开车来回。'],itinerary:[['09:30','Begin around the heritage shophouses while the light is soft. Photograph details without blocking entrances.','趁光线柔和从老店屋开始，拍细节时避开店门。'],['10:30','Explore the lanes and public art, then stop for a cold drink.','逛小巷与公共艺术，再停下来喝杯冷饮。'],['12:00','Choose a lunch spot and leave time for a second-hand book or craft browse.','挑一家午餐店，留点时间看看旧书或手作。']],bring:['Comfortable walking shoes, umbrella and a charged camera or phone.','舒适步行鞋、雨伞、充好电的相机或手机。'],transport:['Use Pasar Seni rail station as a convenient starting point. Routes include busy road crossings.','可从 Pasar Seni 轨道站开始，途中会经过繁忙路口。'],rain:['Stay under the five-foot ways and choose indoor craft shops or cafés between showers.','沿有顶骑楼行走，下雨时逛室内手作店或咖啡馆。']},
    {id:'putrajaya-lakeside',name:['A lakeside afternoon in Putrajaya','布城湖畔的午后'],place:['Putrajaya lakeside','布城湖畔'],area:'Putrajaya',category:'outdoors',cost:20,hours:4,color:'#79a9ad',accent:'#d8d2b8',style:'lake',summary:['Wide paths, architectural views and a late-afternoon breeze. Bring snacks and choose a short section of the waterfront.','宽阔步道、建筑景观、午后微风。带点零食，挑一小段湖岸慢慢走。'],route:['Choose one lakefront area as your base. Distances between landmarks can be longer than they look.','选择一个湖畔区域作为起点，地标之间的距离可能比看起来更远。'],itinerary:[['15:30','Arrive after the strongest midday heat and find a shaded meeting point.','避开正午热浪，下午抵达并找一个有阴凉的集合点。'],['16:00','Walk a manageable lakeside section, pausing for architecture and bridge views.','沿一段适合自己体力的湖岸散步，欣赏建筑与桥景。'],['18:00','Finish with an early dinner nearby before the return trip.','返程前在附近吃一顿早晚餐。']],bring:['Water, hat, umbrella and a light snack. Keep an eye on approaching rain.','水、帽子、雨伞与小零食，留意远处雷雨。'],transport:['Rail reaches Putrajaya Sentral; plan onward local transport to your selected lakefront.','搭轨道交通到 Putrajaya Sentral 后，安排接驳前往选定的湖畔。'],rain:['Switch to an indoor meal and shorten the walk. Avoid exposed waterfront paths during lightning.','下雨改为室内用餐；雷电期间避开无遮蔽的湖畔步道。']},
    {id:'pj-cafe',name:['Coffee, books & a neighbourhood wander','咖啡、书与社区漫游'],place:['Petaling Jaya neighbourhoods','八打灵再也社区'],area:'Selangor',category:'food',cost:45,hours:4,color:'#b69c80',accent:'#dbc7a3',style:'street',summary:['Build a low-pressure afternoon around one good coffee and a stack of books. Choose a small cluster of shops, not a long driving loop.','一杯好咖啡，一叠书，就是轻松午后的起点。选一小片店铺慢逛，不用开车跑远。'],route:['Pick a walkable neighbourhood cluster and check the individual cafés before setting out.','选一个适合步行的社区店铺区，出发前确认想去咖啡馆的营业情况。'],itinerary:[['13:00','Start with lunch and a drink. Set a comfortable budget before ordering.','从午餐和饮料开始，点餐前定好预算。'],['14:00','Browse a bookshop or stationery stop. Save one interesting find to revisit later.','逛书店或文具店，记下一件有趣的发现。'],['15:30','Walk the surrounding streets, then settle into a second quiet stop if you feel like it.','在附近街道散步，愿意的话再找个安静角落坐坐。']],bring:['A book, a reusable bottle and enough room in your bag for an unexpected find.','一本书、可重复使用的水瓶，以及装下意外收获的包。'],transport:['PJ is spread out. Plan one neighbourhood and an onward ride from the nearest suitable rail station.','PJ 范围较大，建议集中一个社区，从适合的轨道站安排接驳。'],rain:['This is a good wet-weather option. Bring an umbrella for the short walks between shops.','适合雨天的选择，带伞应付店铺之间的短距离步行。']},
    {id:'wetland-walk',name:['Green paths & a picnic pause','绿道散步与野餐'],place:['Shah Alam park neighbourhoods','莎阿南公园社区'],area:'Selangor',category:'outdoors',cost:15,hours:3,color:'#6c8f76',accent:'#c8d6a0',style:'garden',summary:['A relaxed local park outing with space to breathe. Choose a maintained public park and pair a short walk with a picnic.','在本地公园轻松透气，选维护良好的公共公园，短途散步后野餐。'],route:['Choose an accessible public park entrance and save your meeting point before leaving home.','选择方便抵达的公共公园入口，出门前保存集合地点。'],itinerary:[['08:00','Start on the maintained paths. Keep the loop short enough for everyone in your group.','从维护良好的步道开始，按同行者的体力决定距离。'],['09:00','Find a permitted shaded picnic spot and take a long break.','找一处允许野餐的树荫位置，慢慢休息。'],['10:00','Pack up all litter and finish with a final easy loop.','带走所有垃圾，最后再轻松绕一小圈。']],bring:['Drinking water, insect repellent, a picnic mat and breakfast.','饮用水、防蚊用品、野餐垫和早餐。'],transport:['Access varies by park. Confirm your chosen entrance and return transport before starting.','不同公园交通条件各异，出发前确认入口和返程方式。'],rain:['Choose a nearby indoor breakfast stop. Wet paths can be slippery, so skip the walk during heavy rain.','雨天改到附近室内早餐店，大雨时跳过湿滑步道。']},
    {id:'gallery-day',name:['An afternoon for art & conversation','艺术与交谈的午后'],place:['KL gallery district','吉隆坡画廊路线'],area:'KL',category:'culture',cost:30,hours:4,color:'#c6a598',accent:'#d9cfbd',style:'gallery',summary:['Pick a small exhibition, spend time with a few works and talk about what you noticed over coffee. No need to see everything.','选一个小展览，认真看几件作品，再喝咖啡聊聊发现。不必看完所有展品。'],route:['Choose a currently open public gallery and check visitor access before travelling.','先选一间当前开放的公共画廊，出发前查看参观规定。'],itinerary:[['13:00','Arrive, read the exhibition introduction and choose a first room.','抵达后阅读展览介绍，选择第一个展厅。'],['14:00','Look closely at three pieces. Note a colour, material or idea you want to remember.','仔细看三件作品，记下一种颜色、材质或想法。'],['15:00','Find a nearby café and trade your favourite observations.','到附近咖啡馆分享各自最喜欢的发现。']],bring:['A small notebook. Check photography rules at the venue before taking pictures.','小笔记本。拍照前确认场馆的摄影规定。'],transport:['Choose a gallery near a rail connection or plan a short onward ride.','可挑选靠近轨道站的画廊，或安排短程接驳。'],rain:['A natural rainy-day plan. Carry an umbrella for the last walk to the venue.','很适合雨天，带伞应付前往场馆的最后一段路。']},
    {id:'melaka-lanes',name:['A day of Melaka lanes & riverside stops','马六甲小巷与河畔一日'],place:['Melaka old town','马六甲老城'],area:'Melaka',category:'culture',cost:80,hours:8,color:'#c37658',accent:'#e3c19c',style:'street',summary:['A full-day wander through old streets and along the river. Leave room for lunch, shade and the occasional wrong turn.','用一天慢逛旧街与河边，留出吃饭、乘凉，甚至偶尔走错路的空间。'],route:['Base your day around the walkable old-town area. This plan starts after you arrive in Melaka.','以适合步行的老城区为中心。本计划从抵达马六甲后开始。'],itinerary:[['09:00','Begin with a quiet river walk before the busiest part of the day.','趁人潮较少先到河边散步。'],['11:00','Explore heritage lanes and choose one small museum or craft stop.','逛历史街巷，并选一个小博物馆或手作店。'],['13:00','Take a long lunch break, then return to the river for a gentler afternoon.','慢慢吃午餐，下午再回到河畔轻松走走。']],bring:['Water, sun protection, umbrella and comfortable shoes. Budget separately for intercity travel.','水、防晒、雨伞和舒适的鞋；城际交通需另外预算。'],transport:['Arrange intercity transport and the final connection into old town in advance.','提前安排城际交通以及抵达老城区的最后一段接驳。'],rain:['Use museums, cafés and covered shopfronts as breaks, and keep the route flexible.','在博物馆、咖啡馆和有顶店面间穿插休息，灵活调整路线。']},
    {id:'penang-stroll',name:['George Town: small details, big appetite','乔治市：看细节，吃好饭'],place:['George Town','乔治市'],area:'Penang',category:'food',cost:65,hours:6,color:'#acb9b2',accent:'#edc287',style:'street',summary:['Walk a compact heritage route, notice the shutters and tiles, then pause for a local meal. Let the day grow from there.','沿紧凑的历史街区路线走走，看百叶窗与花砖，再停下来吃一餐。从这里自由展开一天。'],route:['Start once you are in George Town. Pick a compact route rather than trying to cover the whole island.','本路线从抵达乔治市后开始；选一小片街区，不必一天逛完整座岛。'],itinerary:[['09:00','Begin with breakfast and a short heritage walk while it is cooler.','趁天气较凉，先吃早餐再走一小段老街。'],['11:00','Browse a craft shop or small exhibition, pausing often in the shade.','逛手作店或小展览，多在阴凉处休息。'],['13:00','Choose a lunch stop, then finish with a slow walk back through a different lane.','挑一家午餐店，最后从另一条小巷慢慢走回来。']],bring:['A hat, water, cash for small purchases and a light umbrella.','帽子、水、小额现金和轻便雨伞。'],transport:['Confirm arrival and local transport separately. Watch for traffic on narrow heritage streets.','城际和本地交通请分别安排，狭窄老街步行时留意车辆。'],rain:['Choose indoor stops and postpone exposed walks until the showers pass.','雨天多安排室内停留，阵雨过后再继续无遮蔽的路线。']}
  ];

  const number = n => Number.isInteger(n) ? String(n) : String(Math.round(n * 100) / 100);
  const safeList = (C,key,allowed) => {const v=C.read(key,[]);return Array.isArray(v)?v.filter(x=>allowed.includes(x)):[];};
  const download = (name,text,type='text/plain;charset=utf-8') => {const a=document.createElement('a');const u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000);};
  function foodArt(r,small=false){
    const i=recipes.findIndex(item=>item.id===r.id),col=[0,33.333333,66.666667,100][i%4],row=i<4?0:100;
    return `<div role="img" aria-label="${r.name[0]}" class="food-art food-photo" style="background-image:url(assets/recipe-photography.png);background-size:400% 200%;background-position:${col}% ${row}%"></div>`;
  }
  function eventArt(e,variant=0){
    if(variant===0){
      const i=Math.max(0,outings.findIndex(item=>item.id===e.id)),col=[0,33.333333,66.666667,100][i%4],row=i<4?0:100;
      return `<div role="img" aria-label="${e.place[0]} — location-inspired image" class="event-art event-photo" style="background-image:url(assets/outing-photography.png);background-size:400% 200%;background-position:${col}% ${row}%"></div>`;
    }
    const sky=variant===1?'#f3ddc3':'#d7e4df',base=e.color;
    let scene='';
    if(e.style==='street'){for(let i=0;i<6;i++){let x=i*140-20;scene+=`<rect x="${x}" y="${160+(i%2)*30}" width="143" height="310" fill="${[base,e.accent,'#d4c6a4'][i%3]}" stroke="#68716a" stroke-width="2"/><path d="M${x} ${165+(i%2)*30}l70 -50 72 50" fill="#7a7769"/>`;for(let j=0;j<2;j++)scene+=`<rect x="${x+25+j*62}" y="235" width="35" height="67" rx="18" fill="#4e6662"/><path d="M${x+25+j*62} 257h35m-35 13h35m-35 13h35" stroke="#a4b9ad" stroke-width="3"/>`;scene+=`<path d="M${x+18} 470V365q52 -51 108 0v105" fill="#4b5d55"/><rect x="${x}" y="329" width="140" height="14" fill="#eee1c5"/>`;}scene+=`<path d="M0 465L800 440v100H0z" fill="#c5b6a3"/><path d="M0 495L800 465" stroke="#a69883" stroke-width="3"/>`;
    }else if(e.style==='gallery'){scene=`<rect x="0" y="120" width="800" height="355" fill="#efece3"/><path d="M0 475h800v65H0" fill="#c7b9a4"/><path d="M400 120v355" stroke="#d5cec1" stroke-width="3"/>`;for(let i=0;i<3;i++)scene+=`<rect x="${70+i*245}" y="195" width="165" height="190" fill="#f8f5ed" stroke="#8c775b" stroke-width="8"/><rect x="${83+i*245}" y="208" width="139" height="164" fill="${i===1?base:e.accent}"/><circle cx="${145+i*245}" cy="278" r="44" fill="${i===1?'#decaa8':'#b07863'}"/><path d="M${90+i*245} 354l64 -63 57 63" fill="#687e74"/>`;scene+=`<path d="M110 453h580" stroke="#8b7861" stroke-width="8"/><path d="M145 453v40m510 -40v40" stroke="#8b7861" stroke-width="6"/>`;
    }else{scene=`<path d="M0 275q100 -95 205 -20t210 -20t225 3t160 -19v321H0" fill="${base}"/><path d="M0 347q147 -72 300 -8t280 -12t220 5v208H0" fill="#477b6d"/><path d="M0 410q200 -74 397 -20t403 -17v167H0" fill="${e.style==='garden'?'#9cb779':'#8fbcb8'}"/><path d="M0 473q250 -48 411 -17t389 -12" fill="none" stroke="#d7e0c5" stroke-width="5"/><path d="M0 540q110 -98 238 -120t92 -80q-30 -47 200 -62" fill="none" stroke="#dccfb4" stroke-width="27"/>`;for(let i=0;i<10;i++){let x=(i*117)%830,y=220+i%3*41;scene+=`<path d="M${x} ${y+90}v-80" stroke="#5f6851" stroke-width="9"/><ellipse cx="${x}" cy="${y}" rx="${34+i%3*6}" ry="56" fill="${i%2?'#4d7757':'#71916c'}"/>`;}}
    return `<svg class="event-art" viewBox="0 0 800 540" role="img" aria-label="${e.place[0]}"><rect width="800" height="540" fill="${sky}"/><circle cx="666" cy="92" r="50" fill="#f4d7a0"/><path d="M40 94q80 -34 170 0m250 33q58 -24 120 0" stroke="#f4f1e5" stroke-width="20" fill="none" stroke-linecap="round"/>${scene}<text x="770" y="518" text-anchor="end" fill="#fff" opacity=".75" font-size="13" font-family="Georgia,serif">Out There · illustrated field notes</text></svg>`;
  }
  function renderRecipes(C){
    const {root,params,esc:esc,t}=C,tx=x=>t(x[0],x[1]);
    root.className='pantry-scene';document.title=t('Pantry & Plate — good food, ordinary days','Pantry & Plate — 日常里的好滋味');
    let saved=safeList(C,'bp-recipes-saved',recipes.map(x=>x.id));
    let selected=recipes.find(x=>x.id===params.get('id'));
    let servings=Number(C.read('bp-recipe-servings-'+(selected?.id||''),2));if(![1,2,4,6].includes(servings))servings=2;
    const link=(q={})=>C.url('recipe.html',q);
    const ad=()=>`<aside class="pp-ad-banner" aria-label="${t('Advertisement','广告')}"><small>${t('ADVERTISEMENT','广告')}</small><div><b>Form & Field</b><span>${t('A calmer corner for your everyday table.','给日常餐桌，留一个安静角落。')}</span><a data-br-ad="desk" target="_blank" rel="noopener" href="${C.url('destination.html',{site:'desk',from:'recipes'})}">${t('Explore the collection','浏览家居系列')} ↗</a></div></aside>`;
    const cats=[['all',t('All recipes','所有食谱')],['quick',t('15-minute meals','15 分钟快手餐')],['one-pot',t('One-pan dinners','一锅晚餐')],['vegetarian',t('Vegetarian','素食')]];
    const card=r=>`<article class="pp-card"><a href="${link({id:r.id})}" class="pp-card-image">${foodArt(r,true)}</a><div class="pp-card-copy"><span class="pp-kicker">${tx(r.tag)}</span><h3><a href="${link({id:r.id})}">${tx(r.name)}</a></h3><p>${tx(r.desc)}</p><div class="pp-card-meta"><span>◷ ${r.time} ${t('min','分钟')}</span><span>${t('Serves 2','2 人份')}</span><button type="button" data-save="${r.id}" aria-label="${t('Save','收藏')} ${tx(r.name)}" aria-pressed="${saved.includes(r.id)}">${saved.includes(r.id)?'♥':'♡'}</button></div></div></article>`;
    function draw(){
      saved=safeList(C,'bp-recipes-saved',recipes.map(x=>x.id));
      const q=params.get('q')||'',category=params.get('category')||'all',isSaved=params.get('view')==='saved';
      const filtered=recipes.filter(r=>(category==='all'||r.category===category)&&(!isSaved||saved.includes(r.id))&&`${r.name.join(' ')} ${r.desc.join(' ')} ${r.ingredients.map(x=>x.slice(2).join(' ')).join(' ')}`.toLowerCase().includes(q.toLowerCase()));
      root.innerHTML=`<div class="pp-topline">${t('A little inspiration for your everyday table.','为日常餐桌，添一点灵感。')}</div><header class="pp-header"><a href="${link()}" class="pp-logo">pantry<span>&</span>plate<i>${t('GOOD FOOD. ORDINARY DAYS.','日常里的好滋味')}</i></a><form class="pp-search" action="recipe.html" method="get"><input type="hidden" name="lang" value="${C.lang}">${params.get('seed')?`<input type="hidden" name="seed" value="${esc(params.get('seed'))}">`:''}<label class="visually-hidden" for="pp-search-input">${t('Search recipes','搜索食谱')}</label><input id="pp-search-input" name="q" value="${esc(q)}" placeholder="${t('What would you like to cook?','今天想煮什么？')}"><button aria-label="${t('Search','搜索')}">⌕</button></form><a class="pp-saved-link" href="${link({view:'saved'})}">♡ ${t('My recipe box','我的食谱盒')} <b>${saved.length}</b></a></header><nav class="pp-nav" aria-label="${t('Recipes','食谱')}">${cats.map(([id,name])=>`<a ${category===id&&!isSaved?'aria-current="page"':''} href="${link(id==='all'?{}:{category:id})}">${name}</a>`).join('')}<a href="${link({id:'ginger-rice'})}">${t('Tonight’s pick','今晚推荐')}</a></nav><main class="pp-main">${selected?detail(selected):`${!q&&!isSaved&&category==='all'?`<section class="pp-hero"><div class="pp-hero-copy"><span class="pp-kicker">${t('THE EVERYDAY TABLE','日常餐桌')}</span><h1>${t('Something good.<br>Nothing complicated.','好吃一点。<br>简单一点。')}</h1><p>${t('Reliable recipes, everyday ingredients and the small pleasure of making dinner yourself. Find your next favourite here.','熟悉的食材、可靠的食谱，还有亲手做晚餐的小满足。在这里找到下一道拿手菜。')}</p><a class="pp-button" href="${link({id:'ginger-rice'})}">${t('Make tonight’s dinner','做一顿今晚的晚餐')} <span>→</span></a><small>${t('One-pan ginger chicken & rice · 35 min','一锅姜香鸡肉饭 · 35 分钟')}</small></div><a href="${link({id:'ginger-rice'})}" class="pp-hero-art">${foodArt(recipes[0])}<span>${t('The weeknight favourite','平日晚餐首选')}</span></a></section>`:''}${ad()}<section class="pp-section"><div class="pp-section-head"><div><span class="pp-kicker">${isSaved?t('KEEP THE GOOD ONES','把喜欢的留住'):t('FROM OUR KITCHEN','来自我们的厨房')}</span><h1>${q?`${t('Recipes for','食谱搜索：')} “${esc(q)}”`:isSaved?t('Your recipe box','你的食谱盒'):cats.find(x=>x[0]===category)?.[1]||t('All recipes','所有食谱')}</h1></div><span>${filtered.length} ${t('recipes','道食谱')}</span></div>${filtered.length?`<div class="pp-grid">${filtered.map(card).join('')}</div>`:`<div class="pp-empty"><h2>${t('A fresh start for your recipe box.','从一道好菜开始。')}</h2><p>${t('Try another ingredient, or save a recipe with the heart button.','试着换个食材搜索，或点爱心把食谱加入收藏。')}</p><a class="pp-button" href="${link()}">${t('Explore all recipes','浏览所有食谱')}</a></div>`}</section><section class="pp-note"><span>❧</span><div><h2>${t('Small habits. Better dinners.','小习惯，让晚餐更好吃。')}</h2><p>${t('Read the whole recipe before you start. Get your ingredients ready, keep a little cooking water, and taste as you go. Good cooking is mostly paying attention.','开始前先读完食谱，备好食材，留一点煮面水，并在过程中尝味。好料理，往往从用心开始。')}</p></div><a href="${link({id:'tomato-pasta'})}">${t('Start with pasta →','从一碗意面开始 →')}</a></section>`}</main><footer class="pp-footer"><a class="pp-logo" href="${link()}">pantry<span>&</span>plate</a><p>${t('Tested at home. Shared for your table. Original food imagery made for this collection.','在家实践，为餐桌分享。本站餐点图片为本系列原创。')}</p><a href="${C.url('guide.html')}">${t('About this collection','关于本系列')}</a></footer><div class="pp-toast" role="status" aria-live="polite"></div>`;
    }
    function detail(r){
      const raw=C.read('bp-recipe-steps-'+r.id,[]),checks=Array.isArray(raw)?raw.filter(x=>Number.isInteger(x)&&x>=0&&x<r.steps.length):[];
      const rawIngredients=C.read('bp-recipe-ingredients-'+r.id,[]),ingredientChecks=Array.isArray(rawIngredients)?rawIngredients.filter(x=>Number.isInteger(x)&&x>=0&&x<r.ingredients.length):[];
      document.title=tx(r.name)+' | Pantry & Plate';
      return `<div class="pp-breadcrumb"><a href="${link()}">${t('Recipes','食谱')}</a> / ${tx(r.name)}</div><article class="pp-detail"><header class="pp-detail-heading"><span class="pp-kicker">${tx(r.tag)}</span><h1>${tx(r.name)}</h1><p>${tx(r.desc)}</p><div class="pp-byline">${t('By the Pantry & Plate kitchen · Easy · Everyday ingredients','Pantry & Plate 厨房 · 简单 · 日常食材')}</div><div class="pp-detail-actions"><a class="pp-button" href="#recipe-card">${t('Jump to recipe ↓','直接看食谱 ↓')}</a><button data-save="${r.id}" class="pp-secondary" aria-pressed="${saved.includes(r.id)}">${saved.includes(r.id)?'♥':'♡'} ${saved.includes(r.id)?t('Saved','已收藏'):t('Save recipe','收藏食谱')}</button><button data-print class="pp-secondary">${t('Print','打印')}</button></div></header><div class="pp-detail-visual">${foodArt(r)}</div><div class="pp-detail-layout"><section id="recipe-card" class="pp-recipe-card"><div class="pp-recipe-stats"><div><b>${r.prep} ${t('min','分钟')}</b><span>${t('Prep','备料')}</span></div><div><b>${r.cook} ${t('min','分钟')}</b><span>${t('Cook','烹煮')}</span></div><div><b>${r.time} ${t('min','分钟')}</b><span>${t('Total','共计')}</span></div></div><div class="pp-ingredient-heading"><h2>${t('Ingredients','食材')}</h2><label>${t('Servings','份量')} <select data-servings aria-label="${t('Servings','份量')}">${[1,2,4,6].map(n=>`<option value="${n}" ${n===servings?'selected':''}>${n}</option>`).join('')}</select></label></div><p class="pp-help">${t('Amounts adjust to your chosen servings. Season to taste.','食材数量随份量调整；调味请依口味微调。')}</p><ul class="pp-ingredients">${r.ingredients.map(([n,u,en,zh],i)=>`<li><label><input type="checkbox" class="pp-pantry-check" data-ingredient="${i}" ${ingredientChecks.includes(i)?'checked':''}><span><b>${number(n*servings/2)} ${u}</b> ${t(en,zh)}</span></label></li>`).join('')}</ul><h2>${t('Let’s cook','开始做菜')}</h2><p class="pp-help">${t('Tick each step as you go. Your progress stays in this browser.','边做边勾选，进度会保存在当前浏览器。')}</p><ol class="pp-steps">${r.steps.map((s,i)=>`<li class="${checks.includes(i)?'is-done':''}"><label><input type="checkbox" data-step="${i}" ${checks.includes(i)?'checked':''}><span class="pp-step-num">${i+1}</span><span>${tx(s)}</span></label></li>`).join('')}</ol><p class="pp-progress" aria-live="polite">${checks.length} / ${r.steps.length} ${t('steps complete','步骤已完成')}</p><button class="pp-button" data-recipe-download>${t('Save recipe as a text file','下载食谱文本')} ↓</button></section><aside class="pp-cook-notes"><h2>${t('Kitchen notes','厨房小笔记')}</h2><h3>${t('Make it your own','换个做法')}</h3><p>${tx(r.tip)}</p><h3>${t('Saving leftovers','剩菜保存')}</h3><p>${tx(r.storage)}</p><div class="pp-side-note"><b>${t('Before you start','动手之前')}</b><p>${t('Read through, prepare your ingredients and clear a little space. Check labels if cooking for anyone with allergies.','先通读食谱、备齐食材、整理台面。为过敏人士烹饪前请检查食材标签。')}</p></div>${ad()}</aside></div></article><section class="pp-section"><div class="pp-section-head"><h2>${t('Something for tomorrow','明天也有好吃的')}</h2><a href="${link()}">${t('All recipes →','所有食谱 →')}</a></div><div class="pp-grid pp-related">${recipes.filter(x=>x.id!==r.id).slice(0,3).map(card).join('')}</div></section>`;
    }
    root.addEventListener('click',e=>{const s=e.target.closest('[data-save]');if(s){const id=s.dataset.save;saved=safeList(C,'bp-recipes-saved',recipes.map(x=>x.id));saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];C.write('bp-recipes-saved',saved);const scroll=window.scrollY;draw();window.scrollTo(0,scroll);const focus=root.querySelector(`[data-save="${id}"]`);focus?.focus({preventScroll:true});root.querySelector('.pp-toast').textContent=saved.includes(id)?t('Added to your recipe box','已加入食谱盒'):t('Removed from your recipe box','已移出食谱盒');C.complete(t('Saved a recipe','收藏了一道食谱'));}if(e.target.closest('[data-print]'))window.print();if(e.target.closest('[data-recipe-download]')&&selected){const r=selected;download(`pantry-plate-${r.id}.txt`,`${tx(r.name)}\n${servings} ${t('servings','人份')} · ${r.time} ${t('minutes','分钟')}\n\n${t('Ingredients','食材')}\n${r.ingredients.map(([n,u,en,zh])=>`${number(n*servings/2)} ${u} ${t(en,zh)}`).join('\n')}\n\n${t('Method','做法')}\n${r.steps.map((s,i)=>`${i+1}. ${tx(s)}`).join('\n\n')}\n\n${tx(r.tip)}\n\n${tx(r.storage)}\n\nPantry & Plate`);C.complete(t('Downloaded a recipe','下载了食谱'));}});
    root.addEventListener('change',e=>{if(e.target.matches('[data-ingredient]')){C.write('bp-recipe-ingredients-'+selected.id,[...root.querySelectorAll('[data-ingredient]:checked')].map(x=>Number(x.dataset.ingredient)));}if(e.target.matches('[data-servings]')){servings=Number(e.target.value);C.write('bp-recipe-servings-'+selected.id,servings);const scroll=window.scrollY;draw();window.scrollTo(0,scroll);root.querySelector('[data-servings]')?.focus({preventScroll:true});}if(e.target.matches('[data-step]')){const checks=[...root.querySelectorAll('[data-step]:checked')].map(x=>Number(x.dataset.step));C.write('bp-recipe-steps-'+selected.id,checks);e.target.closest('li').classList.toggle('is-done',e.target.checked);root.querySelector('.pp-progress').textContent=`${checks.length} / ${selected.steps.length} ${t('steps complete','步骤已完成')}`;if(checks.length===selected.steps.length)C.complete(t('Finished a recipe','完成一道料理'));}});
    window.addEventListener('pageshow',event=>{if(!event.persisted)return;const scroll=window.scrollY;if(selected){const currentServings=Number(C.read('bp-recipe-servings-'+selected.id,2));servings=[1,2,4,6].includes(currentServings)?currentServings:2;}draw();window.scrollTo(0,scroll);});
    draw();
  }

  function renderEvents(C){
    const {root,params,esc,t}=C,tx=x=>t(x[0],x[1]),link=(q={})=>C.url('events.html',q);
    root.className='outthere-scene';document.title=t('Out There — make a little room for the weekend','Out There — 给周末留一点空白');
    let saved=safeList(C,'bp-outings-saved',outings.map(x=>x.id));const chosen=outings.find(x=>x.id===params.get('id'));
    const cats=[['all',t('All ideas','所有灵感')],['outdoors',t('Outdoors','户外')],['culture',t('Art & culture','艺术与文化')],['food',t('Food & slow days','吃喝慢生活')]];
    const card=e=>`<article class="ot-card"><a href="${link({id:e.id})}" class="ot-card-art">${eventArt(e)}<span>${e.area}</span></a><div class="ot-card-copy"><div class="ot-kicker">${cats.find(x=>x[0]===e.category)?.[1]}</div><h3><a href="${link({id:e.id})}">${tx(e.name)}</a></h3><p>${tx(e.summary)}</p><div class="ot-meta"><span>◷ ${e.hours} ${t('hours','小时')}</span><span>${e.cost?'~ RM'+e.cost:t('Free outing','免费路线')}</span><button data-outing-save="${e.id}" aria-pressed="${saved.includes(e.id)}" aria-label="${t('Save','收藏')} ${tx(e.name)}">${saved.includes(e.id)?'♥':'♡'}</button></div></div></article>`;
    function draw(){
      saved=safeList(C,'bp-outings-saved',outings.map(x=>x.id));const view=params.get('view'),q=params.get('q')||'',region=params.get('region')||'all',category=params.get('category')||'all',budget=params.get('budget')||'all';
      const results=outings.filter(e=>(region==='all'||e.area===region)&&(category==='all'||e.category===category)&&(budget==='all'||e.cost<=Number(budget))&&`${e.name.join(' ')} ${e.place.join(' ')} ${e.summary.join(' ')}`.toLowerCase().includes(q.toLowerCase())&&(view!=='saved'||saved.includes(e.id)));
      root.innerHTML=`<div class="ot-topline">${t('LOCAL FINDS · SMALL ADVENTURES · GOOD WEEKENDS','本地发现 · 小小冒险 · 美好周末')}</div><header class="ot-header"><a class="ot-logo" href="${link()}">Out There<span>KL & BEYOND</span></a><nav aria-label="${t('Discover','探索')}">${cats.map(([id,n])=>`<a href="${link(id==='all'?{}:{category:id})}" ${id===category?'aria-current="page"':''}>${n}</a>`).join('')}</nav><a class="ot-plan-link" href="${link({view:'saved'})}">♡ ${t('My weekend','我的周末')} <b>${saved.length}</b></a></header><main class="ot-main">${chosen?detail(chosen):`${view!=='saved'&&!q&&category==='all'&&region==='all'&&budget==='all'?`<section class="ot-hero"><a href="${link({id:'lake-morning'})}" class="ot-hero-art">${eventArt(outings[0])}<div><span class="ot-kicker">${t('THIS WEEKEND, TAKE IT SLOW','这个周末，慢一点')}</span><h1>${t('A little closer<br>to outside.','走出去。<br>离日常远一点。')}</h1><span class="ot-hero-link">${t('A slow morning around the lake','湖畔的慢早晨')} ↗</span></div></a><aside><span class="ot-kicker">${t('THE WEEKEND EDIT','周末灵感手记')}</span><h2>${t('You don’t have to go far<br>to find a good day.','好日子，<br>不必去太远。')}</h2><p>${t('Neighbourhood walks, quiet corners and places worth slowing down for. A handful of ideas for your next free afternoon.','社区散步、安静角落，以及值得慢下来的地方。给下一个空闲午后，一点好灵感。')}</p><a href="${link({category:'culture'})}">${t('Find your kind of afternoon →','寻找你的理想午后 →')}</a><div class="ot-editor-note">${t('Local field notes.<br>Plan a route. Leave room to wander.','记录身边的地方。<br>做一点计划，留一点随性。')}</div></aside></section>`:''}<section class="ot-discover"><div class="ot-section-head"><div><span class="ot-kicker">${view==='saved'?t('YOUR OWN LITTLE LIST','属于你的小清单'):t('CLOSE TO HOME','就在不远处')}</span><h1>${view==='saved'?t('Your weekend, coming together.','你的周末，慢慢成形。'):q?`${t('Ideas for','搜索：')} “${esc(q)}”`:t('Where shall we go?','我们去哪里？')}</h1></div><span>${results.length} ${t('ideas','个灵感')}</span></div><form class="ot-filters" method="get" action="events.html"><input type="hidden" name="lang" value="${C.lang}">${params.get('seed')?`<input type="hidden" name="seed" value="${esc(params.get('seed'))}">`:''}${view==='saved'?'<input type="hidden" name="view" value="saved">':''}<label>${t('Find something','找点什么')}<input name="q" value="${esc(q)}" placeholder="${t('Lake, coffee, art…','湖边、咖啡、艺术……')}"></label><label>${t('Area','地区')}<select name="region">${['all','KL','Selangor','Putrajaya','Melaka','Penang'].map(x=>`<option value="${x}" ${x===region?'selected':''}>${x==='all'?t('Anywhere','不限地区'):x}</option>`).join('')}</select></label><label>${t('Kind of day','出游类型')}<select name="category">${cats.map(([id,n])=>`<option value="${id}" ${id===category?'selected':''}>${n}</option>`).join('')}</select></label><label>${t('Outing budget','出游预算')}<select name="budget">${[['all',t('Any budget','不限预算')],['0',t('Free','免费')],['25',t('Up to RM25','RM25 以下')],['50',t('Up to RM50','RM50 以下')]].map(([id,n])=>`<option value="${id}" ${budget===id?'selected':''}>${n}</option>`).join('')}</select></label><button class="ot-button">${t('Find a day out','寻找出游灵感')} →</button></form>${view==='saved'?planner():''}${results.length?`<div class="ot-grid">${results.map(card).join('')}</div>`:`<div class="ot-empty"><h2>${t('Leave a little room for something new.','为新发现留一点位置。')}</h2><p>${t('Try a wider budget or a different area. Tap a heart on any outing to add it to your weekend.','试试更宽的预算或其他地区。点击路线上的爱心，把它加入周末计划。')}</p><a class="ot-button" href="${link()}">${t('Explore all ideas','查看所有灵感')}</a></div>`}</section><section class="ot-note"><span>↗</span><div><h2>${t('A plan is a starting point.','计划，是一个起点。')}</h2><p>${t('Our routes are inspiration, not live listings. Budgets are rough personal allowances and exclude travel. Confirm access, opening hours, weather and venue prices before heading out.','这些路线提供灵感，并非即时活动列表。预算是个人参考额，不含交通。出发前请确认开放情况、营业时间、天气与场馆票价。')}</p></div></section>`}</main><aside class="ot-ad-banner" aria-label="${t('Advertisement','广告')}"><small>${t('ADVERTISEMENT','广告')}</small><div><span>FORM & FIELD</span><p>${t('Good things for the days you stay in.','留在家的日子，也有好风景。')}</p><a data-br-ad="desk" target="_blank" rel="noopener" href="${C.url('destination.html',{site:'desk',from:'events'})}">${t('Shop home & living','浏览家居好物')} ↗</a></div></aside><footer class="ot-footer"><a class="ot-logo" href="${link()}">Out There<span>KL & BEYOND</span></a><p>${t('A good day can start around the corner. Original local guides.','美好的一天，可以从转角开始。原创本地指南。')}</p><a href="${C.url('guide.html')}">${t('About these guides','关于本系列')}</a></footer><div class="ot-toast" role="status" aria-live="polite"></div>`;
    }
    function planner(){const items=outings.filter(x=>saved.includes(x.id));return `<section class="ot-planner"><div><h2>${t('Make a little plan','做个小计划')}</h2><p>${t('Keep a short list, choose a date and take it with you.','保留一个短清单，挑个日期，然后带着计划出门。')}</p></div><div class="ot-plan-controls"><label>${t('Date','日期')} <input type="date" data-plan-date value="${esc(String(C.read('bp-outing-date','')))}"></label><button data-plan-download class="ot-button" ${!items.length?'disabled':''}>${t('Download my plan','下载出游计划')} ↓</button></div>${items.length?`<p>${items.length} ${t('saved ideas · approximate combined activity time:','个收藏路线 · 参考活动总时长：')} ${items.reduce((n,x)=>n+x.hours,0)} ${t('hours. Pick one or two for a comfortable day.','小时。一天挑一两个路线会更轻松。')}</p>`:''}</section>`;}
    function detail(e){document.title=tx(e.name)+' | Out There';return `<div class="ot-breadcrumb"><a href="${link()}">${t('Explore','探索')}</a> / <a href="${link({region:e.area})}">${e.area}</a> / ${tx(e.place)}</div><article class="ot-detail"><header><span class="ot-kicker">${e.area} · ${cats.find(x=>x[0]===e.category)?.[1]}</span><h1>${tx(e.name)}</h1><p>${tx(e.summary)}</p><div class="ot-byline">${t('Out There field notes · Local guides','Out There 本地手记 · 本地指南')}</div></header><div class="ot-detail-image">${eventArt(e)}</div><div class="ot-detail-body"><div class="ot-detail-story"><div class="ot-facts"><div><b>${e.hours} ${t('hours','小时')}</b><span>${t('Easy-going route','轻松路线')}</span></div><div><b>${e.cost?'~ RM'+e.cost:t('Free','免费')}</b><span>${t('Personal allowance, excluding travel','个人参考预算，不含交通')}</span></div><div><b>${tx(e.place)}</b><span>${t('Your starting area','出发区域')}</span></div></div><h2>${t('A day, loosely planned','一份轻松的行程')}</h2><p>${tx(e.route)}</p><ol class="ot-itinerary">${e.itinerary.map(([time,en,zh])=>`<li><time>${time}</time><div><h3>${t(en.split('. ')[0],zh.split('。')[0])}</h3><p>${t(en,zh)}</p></div></li>`).join('')}</ol><h2>${t('A few more details','再看一点细节')}</h2><div class="ot-gallery"><figure>${eventArt(e,1)}<figcaption>${t('A change of light, a different pace.','换一种光线，换一种节奏。')}</figcaption></figure><figure>${eventArt({...e,style:e.style==='street'?'gallery':'garden'},2)}<figcaption>${t('Leave space for an unexpected stop.','为意外的停留留一点空白。')}</figcaption></figure></div><details class="ot-details"><summary>${t('If the weather changes','如果天气有变')}</summary><p>${tx(e.rain)}</p></details><details class="ot-details"><summary>${t('Getting there & getting home','去程与返程')}</summary><p>${tx(e.transport)}</p></details><p class="ot-smallprint">${t('Images are original location-inspired creations; illustrations are impressions rather than venue maps. These are evergreen route suggestions: confirm current access and conditions before travelling.','图片为按地点主题原创制作的画面，插画为主题印象而非场馆地图。这是常设路线灵感；出发前请确认当前开放情况。')}</p></div><aside class="ot-pack"><span class="ot-kicker">${t('SAVE A GOOD DAY','收藏一个好日子')}</span><h2>${t('Put this on your list.','把这一天，放进清单。')}</h2><button class="ot-button" data-outing-save="${e.id}" aria-pressed="${saved.includes(e.id)}">${saved.includes(e.id)?'♥':'♡'} ${saved.includes(e.id)?t('Saved to my weekend','已加入我的周末'):t('Save this outing','收藏这条路线')}</button><a href="${link({view:'saved'})}">${t('Open my weekend →','打开我的周末 →')}</a><hr><h3>${t('Bring along','随身带上')}</h3><p>${tx(e.bring)}</p><h3>${t('Before you go','出发之前')}</h3><p>${t('Check the forecast, venue access and local transport. Share your meeting point with your group.','确认天气、场馆开放与本地交通。和同行者分享集合点。')}</p><a class="ot-calendar" href="#" data-calendar>${t('Add a day to my calendar','导出日历提醒')} ↓</a></aside></div></article><section class="ot-discover"><div class="ot-section-head"><h2>${t('Another kind of weekend','另一种周末')}</h2><a href="${link()}">${t('All ideas →','所有灵感 →')}</a></div><div class="ot-grid">${outings.filter(x=>x.id!==e.id).slice(0,3).map(card).join('')}</div></section>`;}
    root.addEventListener('click',e=>{const button=e.target.closest('[data-outing-save]');if(button){let id=button.dataset.outingSave;saved=safeList(C,'bp-outings-saved',outings.map(x=>x.id));saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];C.write('bp-outings-saved',saved);const scroll=window.scrollY;draw();window.scrollTo(0,scroll);root.querySelector(`[data-outing-save="${id}"]`)?.focus({preventScroll:true});root.querySelector('.ot-toast').textContent=saved.includes(id)?t('Added to your weekend','已加入你的周末'):t('Removed from your weekend','已移出你的周末');C.complete(t('Saved an outing','收藏一条出游路线'));}if(e.target.closest('[data-plan-download]')){const items=outings.filter(x=>saved.includes(x.id));download('out-there-weekend.txt',`Out There — ${t('My weekend','我的周末')}\n${C.read('bp-outing-date','')}\n\n${items.map(x=>`${tx(x.name)}\n${tx(x.place)} · ${x.hours}h · ${x.cost?'~RM'+x.cost:t('Free','免费')}\n${x.itinerary.map(([time,en,zh])=>time+' '+t(en,zh)).join('\n')}\n${tx(x.bring)}\n${tx(x.transport)}`).join('\n\n')}\n\n${t('Confirm venue access, weather and transport before travelling. Budgets exclude travel.','出发前确认场馆、天气和交通。预算不含交通费。')}`);C.complete(t('Downloaded a weekend plan','下载周末计划'));}if(e.target.closest('[data-calendar]')&&chosen){e.preventDefault();const stored=String(C.read('bp-outing-date',''));const d=/^\d{4}-\d{2}-\d{2}$/.test(stored)?stored.replaceAll('-',''):new Date(Date.now()+86400000).toISOString().slice(0,10).replaceAll('-','');const end=new Date(`${d.slice(0,4)}-${d.slice(4,6)}-${d.slice(6,8)}T00:00:00Z`);end.setUTCDate(end.getUTCDate()+1);const endDate=end.toISOString().slice(0,10).replaceAll('-','');download('out-there-'+chosen.id+'.ics',`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Out There//Weekend Plan//EN\r\nBEGIN:VEVENT\r\nUID:${chosen.id}-${d}@outthere.local\r\nDTSTAMP:${new Date().toISOString().replaceAll('-','').replaceAll(':','').replace(/\.\d{3}/,'')}\r\nDTSTART;VALUE=DATE:${d}\r\nDTEND;VALUE=DATE:${endDate}\r\nSUMMARY:${tx(chosen.name)}\r\nLOCATION:${tx(chosen.place)}\r\nDESCRIPTION:${t('Check access and weather before travelling.','出发前确认开放情况与天气。')}\r\nEND:VEVENT\r\nEND:VCALENDAR`,'text/calendar;charset=utf-8');C.complete(t('Saved an outing to calendar','导出出游日历'));}});
    root.addEventListener('change',e=>{if(e.target.matches('[data-plan-date]'))C.write('bp-outing-date',e.target.value);});
    window.addEventListener('pageshow',event=>{if(!event.persisted)return;const scroll=window.scrollY;draw();window.scrollTo(0,scroll);});
    draw();
  }
  window.BROWSE_SCENES=Object.assign(window.BROWSE_SCENES||{},{recipes:renderRecipes,events:renderEvents});
})();
